const dialogue = contract.dialogue || {};
const dialogueTurns = Array.isArray(dialogue.turns) ? dialogue.turns : [];
const lastTurn = dialogueTurns.length ? dialogueTurns[dialogueTurns.length - 1] : {};
// Развилка (`dialogue.fork`) — последняя пара диалога: её ответ тоже
